//! RFC 3161 timestamp-token verification against OpenSSL (CAP-14).
//!
//! Pre-registered in tests/fixtures/evidence_tsa/PREREGISTRATION.md (committed alone, 30ad70b2)
//! before this verifier existed; the OpenSSL verdicts were then regenerated by
//! `run_openssl.sh`. Bars: B1, the PASS/FAIL verdict agrees with OpenSSL's on every one of the
//! 27 cases; B2, the genTime agrees to the second. Reasons are printed side by side, not scored.

use kshana::evidence::tsa::{pem_certificates, verify_token};
use std::path::Path;

const DIR: &str = "tests/fixtures/evidence_tsa";

fn certs(list: &str) -> Vec<Vec<u8>> {
    if list == "-" {
        return Vec::new();
    }
    list.split(',')
        .flat_map(|f| {
            let t = std::fs::read_to_string(Path::new(DIR).join("certs").join(f)).expect("cert");
            pem_certificates(&t).expect("pem")
        })
        .collect()
}

#[test]
fn every_case_agrees_with_openssl() {
    let verdicts = std::fs::read_to_string(Path::new(DIR).join("openssl-verdicts.txt")).unwrap();
    let cases = std::fs::read_to_string(Path::new(DIR).join("cases.tsv")).unwrap();
    let mut n = 0;
    let mut misses = Vec::new();
    for line in cases
        .lines()
        .filter(|l| !l.starts_with('#') && !l.is_empty())
    {
        let f: Vec<&str> = line.split('\t').collect();
        let (id, tok, data, anchors, untrusted) = (f[0], f[1], f[2], f[3], f[4]);
        let oracle = verdicts
            .lines()
            .find(|l| l.split(' ').next() == Some(id))
            .unwrap_or_else(|| panic!("{id}: no OpenSSL verdict"));
        let o: Vec<&str> = oracle.splitn(5, ' ').collect();
        let (want, want_t) = (o[1] == "PASS", o[3].parse::<i64>().unwrap());
        let token = std::fs::read(Path::new(DIR).join("tokens").join(tok)).unwrap();
        let data = std::fs::read(Path::new(DIR).join(data)).unwrap();
        let v = verify_token(&token, &data, &certs(anchors), &certs(untrusted));
        println!(
            "{id} kshana={} openssl={} kshana_reason={:?} openssl_reason={:?}",
            if v.pass { "PASS" } else { "FAIL" },
            o[1],
            v.reason,
            o[4]
        );
        if v.pass != want {
            misses.push(format!("B1 {id}: kshana {} vs openssl {}", v.pass, want));
        }
        if v.gen_time_unix != Some(want_t) {
            misses.push(format!(
                "B2 {id}: genTime {:?} vs {want_t}",
                v.gen_time_unix
            ));
        }
        n += 1;
    }
    assert_eq!(n, 27, "the 27 registered cases");
    assert!(
        misses.is_empty(),
        "disagreements with OpenSSL:\n{}",
        misses.join("\n")
    );
}
